function draw(){let result=current,s=sourceState,mapping=suggest(result,s,sourceProject),leaves=result.rows.filter(r=>!r.summary),summaries=result.rows.length-leaves.length;document.getElementById('schedulePreview').innerHTML='<h3>'+leaves.length+' atividades e '+summaries+' etapas-resumo</h3>'+result.errors.map(e=>'<p class="notice red-text">'+h(e)+'</p>').join('')+'<p class="notice neutral">'+result.warnings.map(h).join('<br>')+'<br>Atividades já existentes no cronograma mantêm quantidades e execução; serão atualizados início, término, sequência, responsável e predecessoras. Novas atividades usam unidade %, quantidade 100, o avanço do PDF e valor zero. O orçamento, as medições e os valores financeiros não são alterados.</p><p class="section-note">Etapas identificadas: '+h(result.rows.filter(r=>r.summary).map(r=>r.name).join(' · '))+'</p><p>Revise o destino de todas as linhas. Nenhum registro existente será excluído.</p><div class="table-wrap"><table><thead><tr><th>EDT / atividade</th><th>Início / término</th><th>Duração original</th><th>Planejado / concluído</th><th>Predecessoras (Id do PDF)</th><th>Destino no cronograma</th></tr></thead><tbody>'+leaves.map(r=>'<tr><td class="wrap"><strong>'+h(r.name)+'</strong><small class="source-line">EDT '+h(r.wbs)+' · Id '+h(r.sourceId)+'</small></td><td>'+h(r.start)+'<br>'+h(r.finish)+'</td><td>'+h(r.durationOriginal)+'</td><td>'+r.planned+'% / '+r.completed+'%</td><td>'+h(r.predecessors.join('; '))+'</td><td><select aria-label="Destino de '+h(r.name)+'" data-schedule-map="'+h(r.sourceId)+'"><option value="new">Criar atividade de planejamento</option><option value="skip">Ignorar esta linha</option>'+s.activities.filter(a=>a.project===sourceProject).map(a=>'<option value="'+h(a.id)+'" '+(mapping[r.sourceId]===a.id?'selected':'')+'>'+h(a.name)+'</option>').join('')+'</select></td></tr>').join('')+'</tbody></table></div><label class="inline-check"><input type="checkbox" id="scheduleConfirm"> Conferi a obra de destino, as datas e os vínculos acima.</label><p id="scheduleImportError" class="red-text" role="alert"></p><button type="button" class="button primary" id="scheduleCommit" disabled>Importar cronograma</button>';let check=document.getElementById('scheduleConfirm'),button=document.getElementById('scheduleCommit');check.onchange=()=>button.disabled=!check.checked||!!result.errors.length;for(let select of document.querySelectorAll('[data-schedule-map]'))select.onchange=()=>{check.checked=false;button.disabled=true};button.onclick=()=>{try{let map=Object.fromEntries([...document.querySelectorAll('[data-schedule-map]')].map(el=>[el.dataset.scheduleMap,el.value]));commit(sourceProject,current,map,filename,sourceState);}catch(e){document.getElementById('scheduleImportError').textContent=e.message}}}
function commit(project,result,mapping,filename,expected=bridge.getState()){if(JSON.stringify(bridge.getState())!==JSON.stringify(expected))throw Error('Os dados mudaram. Feche e abra a importação novamente.');let imported=apply(expected,project,result,mapping,filename);bridge.save(imported.state);document.querySelector('#reader').close();bridge.done(imported);bridge.toast('Cronograma aplicado em Etapas e atividades: '+imported.created+' novas e '+imported.updated+' atualizadas.');return imported}
